(() => {
const assets = {"vision_bundle.mjs":"","gesture_recognizer.task":"","vision_wasm_internal.js":"","vision_wasm_internal.wasm":"","vision_wasm_nosimd_internal.js":"","vision_wasm_nosimd_internal.wasm":""};

window.createOfflineHandDetector = async function (options) {
  const unpack = async (name, type) => {
    const binary = atob(assets[name]);
    const compressed = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index++) {
      compressed[index] = binary.charCodeAt(index);
    }
    const bytes = new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));
    return new Blob([await new Response(bytes).arrayBuffer()], {type});
  };
  const urls = [];
  const localURL = async (name, type) => {
    const url = URL.createObjectURL(await unpack(name, type));
    urls.push(url);
    return url;
  };
  try {
    const sdk = await localURL('vision_bundle.mjs', 'text/javascript');
    const {GestureRecognizer, FilesetResolver} = await import(sdk);
    const prefix = await FilesetResolver.isSimdSupported()
      ? 'vision_wasm_internal' : 'vision_wasm_nosimd_internal';
    const wasmLoaderPath = await localURL(prefix + '.js', 'text/javascript');
    const wasmBinaryPath = await localURL(prefix + '.wasm', 'application/wasm');
    const model = await unpack('gesture_recognizer.task', 'application/octet-stream');
    const modelAssetBuffer = new Uint8Array(await model.arrayBuffer());
    return await GestureRecognizer.createFromOptions({wasmLoaderPath, wasmBinaryPath}, {
      ...options, baseOptions: {modelAssetBuffer, delegate: 'CPU'}
    });
  } finally {
    urls.forEach(url => URL.revokeObjectURL(url));
  }
};
})();
